CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT NOT NULL UNIQUE,nom TEXT NOT NULL,pw_hash TEXT NOT NULL,salt TEXT NOT NULL,accord TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_data(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,k TEXT NOT NULL,v TEXT NOT NULL,updated INTEGER NOT NULL,PRIMARY KEY(user_id,k));
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS attempts(email TEXT PRIMARY KEY,n INTEGER NOT NULL,until INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ai_usage(user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,day INTEGER NOT NULL,n INTEGER NOT NULL,PRIMARY KEY(user_id,day));
CREATE TABLE IF NOT EXISTS certs(num TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,titulaire TEXT NOT NULL,issued INTEGER NOT NULL,data TEXT,revoked INTEGER NOT NULL DEFAULT 0,UNIQUE(user_id,type));
CREATE TABLE IF NOT EXISTS exam_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,started INTEGER NOT NULL,ends INTEGER NOT NULL,seed INTEGER NOT NULL,qids TEXT NOT NULL,cas TEXT NOT NULL,status TEXT NOT NULL,qcm INTEGER,cas_s INTEGER,final INTEGER,passed INTEGER,detail TEXT);
CREATE INDEX IF NOT EXISTS idx_exam_attempts_user ON exam_attempts(user_id,started);
CREATE TABLE IF NOT EXISTS qbank(id INTEGER PRIMARY KEY AUTOINCREMENT,q TEXT NOT NULL,o TEXT NOT NULL,ok INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS cfg(k TEXT PRIMARY KEY,v TEXT NOT NULL);
